import {supabase,currentUser} from './auth-client.mjs';
import {validateAudit} from './version-audit-model.mjs';
const $=id=>document.getElementById(id),el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
const registry=await fetch(new URL('./version-audit-registry.json',import.meta.url)).then(r=>r.json());
let state={reports:[],findings:[],reviews:[]},busy=false,limit=50;
const statuses={needs_review:'Needs review',verified:'Verified',needs_update:'Needs update',unknown:'Unknown',not_applicable:'Not applicable'};
function message(text){$('version-status').textContent=text;}
async function rpc(action,payload={}){const {data,error}=await supabase.rpc('admin_version_audit',{p_action:action,p_payload:payload});if(error)throw Error(error.message);return data;}
async function act(task){if(busy)return;busy=true;try{await task();}catch(e){message(e.message);}finally{busy=false;}}
function reviewFor(report,id){return state.findings.find(f=>f.report_id===report&&f.finding_id===id);}
function renderFindings(){const entry=state.reports.find(r=>r.report_id===$('audit-report').value),report=entry?.report;const guide=$('audit-guide').value,status=$('audit-filter').value;const rows=(report?.findings??[]).filter(f=>(!guide||f.guideKey===guide)&&(!status||(reviewFor(entry.report_id,f.id)?.status??'needs_review')===status));$('version-findings').replaceChildren();$('audit-summary').textContent=report?report.fromVersion+' → '+report.toVersion+' · '+report.totalChanges+' detected changes'+(report.truncated?' · Report truncated; investigate remaining changes':''):'Import a report to review changed game data.';
 for(const f of rows.slice(0,limit)){const saved=reviewFor(entry.report_id,f.id),card=el('article');card.className='version-finding';card.append(el('h3',f.title+' · '+f.kind.replaceAll('_',' ')),el('p',f.source+' · '+f.path),el('p','Affected sections: '+f.sections.join(', ')));const diff=el('div');diff.className='version-diff';for(const [label,value] of [['Before',f.before],['After',f.after]]){const col=el('div');col.append(el('strong',label),el('pre',String(value)));diff.append(col);}card.append(diff,el('p',f.note));const label=el('label','Review result'),select=el('select');for(const [value,title] of Object.entries(statuses)){const o=el('option',title);o.value=value;select.append(o);}select.value=saved?.status??'needs_review';label.append(select);const note=el('label','Evidence / reason'),input=el('textarea');input.rows=3;input.maxLength=3000;input.value=saved?.note??'';note.append(input);const save=el('button','Save review');save.type='button';save.onclick=()=>act(async()=>{await rpc('review_finding',{report:entry.report_id,finding:f.id,revision:saved?.revision??0,status:select.value,note:input.value});await refresh();message('Finding reviewed. Guide content was not changed.');});const open=el('button','Open guide editor');open.type='button';open.onclick=()=>{document.querySelector('[data-panel="content-panel"]').click();$('page-select').value='events/'+f.guideKey+'.html';$('page-select').dispatchEvent(new Event('change'));};card.append(label,note,save,open);$('version-findings').append(card);}
 if(report&&!rows.length)$('version-findings').append(el('p',report.findings.length?'No findings match these filters.':'No source changes detected. This does not verify live server rules or descriptions.'));$('audit-more').hidden=rows.length<=limit;
}
function renderCoverage(){const table=$('version-coverage');table.replaceChildren();for(const g of registry.guides){const latest=state.reviews.find(r=>r.guide_key===g.key&&r.section_key==='whole-guide');const row=el('tr');for(const text of [g.title,g.baselineVersion,latest?.game_version??'Not recorded',latest?statuses[latest.status]:'Baseline only',latest?new Date(latest.reviewed_at).toLocaleDateString():'—'])row.append(el('td',text));table.append(row);}const list=$('guide-review-history');list.replaceChildren(...state.reviews.slice(0,30).map(r=>el('li',new Date(r.reviewed_at).toLocaleString()+' · '+r.guide_key+' / '+r.section_key+' · '+r.game_version+' · '+statuses[r.status]+' · '+r.note)));}
async function refresh(){if(!await currentUser())return;try{state=await rpc('load');const selected=$('audit-report').value;$('audit-report').replaceChildren(...state.reports.map(r=>{const o=el('option',r.report.fromVersion+' → '+r.report.toVersion+' · '+new Date(r.created_at).toLocaleDateString());o.value=r.report_id;return o;}));if(state.reports.some(r=>r.report_id===selected))$('audit-report').value=selected;renderFindings();renderCoverage();message('Audit workspace ready. Published text and player data are unchanged.');}catch{message('Apply migration 013 to activate audit imports and review history.');renderCoverage();}}
for(const id of ['audit-guide','review-guide']){const options=registry.guides.map(g=>{const o=el('option',g.title);o.value=g.key;return o;});if(id==='audit-guide'){const all=el('option','All guides');all.value='';options.unshift(all);}$(id).replaceChildren(...options);}
function sections(){const g=registry.guides.find(g=>g.key===$('review-guide').value);$('review-section').replaceChildren(...[{key:'whole-guide',title:'Entire guide'},...g.sections].map(s=>{const o=el('option',s.title);o.value=s.key;return o;}));}sections();$('review-guide').onchange=sections;
for(const id of ['audit-report','audit-guide','audit-filter'])$(id).onchange=()=>{limit=50;renderFindings();if(id==='audit-report'){const report=state.reports.find(r=>r.report_id===$('audit-report').value)?.report;if(report)$('review-version').value=report.toVersion;}};$('audit-more').onclick=()=>{limit+=50;renderFindings();};
$('import-version-report').onclick=()=>act(async()=>{const file=$('version-file').files[0];if(!file||file.size>1000000)throw Error('Choose an audit JSON report under 1 MB.');const report=validateAudit(JSON.parse(await file.text()),registry);await rpc('import',{report});await refresh();$('audit-report').value=report.reportId;$('review-version').value=report.toVersion;renderFindings();message('Report imported. Your published guide edits were preserved.');});
$('guide-review-form').onsubmit=e=>{e.preventDefault();act(async()=>{await rpc('guide_review',{guide:$('review-guide').value,section:$('review-section').value,version:$('review-version').value.trim(),status:$('review-status').value,note:$('review-note').value});await refresh();message('Guide verification recorded. This is a review record, not a website publication.');});};
$('download-version-review').onclick=()=>{const blob=new Blob([JSON.stringify({formatVersion:1,exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='milkroad-version-review-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
document.querySelector('[data-panel="version-panel"]').addEventListener('click',()=>refresh());
